function addToCart(id,qty=1,unitType='piece'){const p=allProducts.find(x=>x.id===id);if(!p)return;if(unitType!=='pack'&&(p.saleMode==='pack'||p.piecePriceEntered===false)){toast('This product is configured to sell by pack only.');return}if(unitType==='pack'&&p.saleMode==='piece'){toast('This product is configured to sell by piece only.');return}const packSize=Math.max(1,Number(p.packSize)||1),isPack=unitType==='pack',stockQty=qty*(isPack?packSize:1),unitPrice=isPack?Number(p.packPrice??(Number(p.price||0)*packSize)):Number(p.price||0);const row=cart.find(x=>x.productId===id&&x.unitType===(isPack?'pack':'piece'));const used=cart.filter(x=>x.productId===id).reduce((a,x)=>a+(Number(x.stockQty??x.qty)||0),0);if(used+stockQty>p.stock){toast('Not enough stock available.');return}if(row)row.qty+=qty;else cart.push({productId:id,name:p.name,price:unitPrice,qty,unitType:isPack?'pack':'piece',stockQty,packSize});if(row)row.stockQty+=stockQty;renderCart()}
