function updateMobileCartBar(){const count=document.getElementById('mobileCartItemCount'),totalEl=document.getElementById('mobileCartSubtotal'),bar=document.getElementById('mobileCartBar');if(!count||!totalEl||!bar)return;const units=cart.reduce((a,x)=>a+(Number(x.qty)||0),0),subtotal=cart.reduce((a,x)=>a+(Number(x.price)||0)*(Number(x.qty)||0),0);count.textContent=`${units} ${units===1?'item':'items'}`;totalEl.textContent=money(subtotal);if(units>0){bar.style.removeProperty('display')}else{bar.style.display='none';document.body.classList.remove('mobile-cart-open')}}
