 for(const x of cart){const p=allProducts.find(y=>y.id===x.productId);if(!p||p.stock<Number(x.stockQty??x.qty)){toast(`Stock changed for ${x.name}. Please review the cart.`);await render();return}}
 document.getElementById('overlay').innerHTML=`<div class="modal-back" id="saleConfirmBackdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="saleConfirmTitle"><div class="page-head"><div><h3 id="saleConfirmTitle">Preview &amp; Confirm</h3><div class="muted small">Review the items before stock is deducted.</div></div></div><div class="sale-confirm-summary"><div class="sale-confirm-items">${cart.map(x=>`<div class="sale-confirm-item"><span>${esc(x.name)} × ${x.qty} ${x.unitType==='pack'?'pack(s)':'piece(s)'}</span><strong>${money(x.price*x.qty)}</strong></div>`).join('')}</div><div class="total-line"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="total-line"><span>Discount</span><strong>− ${money(discount)}</strong></div><div class="total-line"><span>Payment method</span><strong>${esc(payment)}</strong></div>${payment==='Cash'?`<div class="total-line"><span>Cash received</span><strong>${money(received)}</strong></div>`:''}${payment==='Borrow'?`<div class="total-line"><span>Customer</span><strong>${esc(customer.name)}</strong></div><div class="total-line"><span>Previous outstanding</span><strong>${money(existingCreditBalance)}</strong></div><div class="total-line"><span>This credit sale</span><strong>${money(total)}</strong></div><div class="total-line"><span>New total outstanding</span><strong>${money(existingCreditBalance+total)}</strong></div><div class="total-line"><span>Payment received now</span><strong>${money(0)}</strong></div>`:''}<div class="confirm-total"><span>${payment==='Borrow'?'Credit sale total':'Total to charge'}</span><strong>${money(total)}</strong></div></div><div class="notice">${payment==='Cash'&&received<total?'⚠ Cash received is less than the sale total. Verify the amount before confirming. ':''}${payment==='Borrow'?'This sale will be added to the selected customer’s udhaar balance. No cash will be recorded as received. ':''}Confirm only after checking the products, quantities, discount, and payment method. This action records the sale and reduces stock.</div><div class="actions"><button type="button" class="secondary" id="cancelSaleConfirm">Cancel sale</button><button type="button" id="confirmSaleNow">✓ Confirm & Sell</button></div></div></div>`;
