   const sale={id:uid(),receipt:'RSS-'+new Date().toISOString().replace(/[-:TZ.]/g,'').slice(0,14)+'-'+Math.floor(Math.random()*90+10),date:new Date().toISOString(),items:cart.map(x=>({...x})),subtotal,discount,total,payment,cashReceived:payment==='Borrow'?0:received,change:payment==='Borrow'?0:Math.max(0,received-total),customerId:payment==='Borrow'?customer.id:null,customerName:payment==='Borrow'?customer.name:null,creditOutstanding:payment==='Borrow'?total:0,status:'completed'};
