async function runSelectiveCleanup(){const target=document.getElementById('cleanupTarget')?.value;if(!['expenses','purchases','cashSales'].includes(target)){toast('That data category cannot be cleared here.');return}const labels={expenses:'business expense logs',purchases:'purchase/restocking logs',cashSales:'non-credit sales history (cash and other non-Udhaar sales)'};if(!confirm(`This will permanently clear ${labels[target]} only. Products, customers, Borrow/Udhaar sales and credit repayment records will be kept. Export a backup first. Continue?`))return;try{if(target==='cashSales'){const rows=await getAll('sales');const remove=rows.filter(x=>x.payment!=='Borrow');for(const row of remove)await del('sales',row.id);toast(`Cleared ${remove.length} non-credit sales records. Udhaar sales were preserved.`)}else{const rows=await getAll(target);for(const row of rows)await del(target,row.id);toast(`Cleared ${rows.length} ${labels[target]}.`)}await render()}catch(e){toast('Cleanup failed: '+e.message)}}
let firebaseApp=null,firebaseDb=null,firebaseAuth=null;
function withFirebaseTimeout(promise,ms,label){
  let timer;
  return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(label+' timed out after '+Math.round(ms/1000)+' seconds. Check internet access, Firebase Authentication settings, and the API key/project ID.')),ms)})]).finally(()=>clearTimeout(timer));
}
async function initFirebase(){
  const config=getFirebaseConfig();
  if(!config||!config.apiKey||!config.projectId||!config.appId)throw new Error('Firebase setup is incomplete. Save API key, Project ID and App ID first.');
  if(!navigator.onLine)throw new Error('Device is offline. Local POS is still available; reconnect to sync.');
  if(!window.firebase||!firebase.initializeApp||!firebase.firestore||!firebase.auth)throw new Error('Firebase SDK did not load. Open the POS with internet access and make sure www.gstatic.com is not blocked.');
  const normalized={apiKey:config.apiKey,authDomain:config.authDomain||`${config.projectId}.firebaseapp.com`,projectId:config.projectId,appId:config.appId};
  if(!firebaseApp||firebaseApp.options.projectId!==normalized.projectId||firebaseApp.options.appId!==normalized.appId){
    const existing=firebase.apps.find(a=>a.options.projectId===normalized.projectId&&a.options.appId===normalized.appId);
    firebaseApp=existing||firebase.initializeApp(normalized,`ronyal-pos-${normalized.projectId}`);
    firebaseDb=firebaseApp.firestore();firebaseAuth=firebaseApp.auth();
  }else{firebaseDb=firebaseApp.firestore();firebaseAuth=firebaseApp.auth();}
  if(!firebaseAuth.currentUser){
    try { await withFirebaseTimeout(firebaseAuth.signInAnonymously(),15000,'Firebase anonymous sign-in'); }
    catch(e){
      if(e.code==='auth/operation-not-allowed')throw new Error('Anonymous sign-in is disabled. Firebase Console → Authentication → Sign-in method → Anonymous → Enable.');
      if(e.code==='auth/invalid-api-key')throw new Error('Firebase API key is invalid. Copy the Web app API key from Project settings.');
      if(e.code==='auth/network-request-failed')throw new Error('Firebase sign-in could not reach Google. Check internet, VPN, DNS, and browser access.');
      throw e;
    }
  }
  if(!firebaseAuth.currentUser)throw new Error('Firebase sign-in did not finish. Try again after checking the network.');
  return firebaseDb;
}
const FIREBASE_STORES=['products','sales','expenses','customers','suppliers','purchases','creditPayments','returns'];
function getFirebaseConfig(){try{return JSON.parse(localStorage.getItem('ronyalFirebaseConfig')||'null')}catch{return null}}
function getStoreSyncId(){let id=(document.getElementById('fbStoreId')?.value||localStorage.getItem('ronyalStoreSyncId')||'').trim();if(!id){id=Array.from(crypto.getRandomValues(new Uint8Array(18))).map(x=>x.toString(16).padStart(2,'0')).join('');localStorage.setItem('ronyalStoreSyncId',id)}return id}
function cloudStoreRoot(dbf){const id=(localStorage.getItem('ronyalStoreSyncId')||'').trim();if(!id)throw new Error('Save a Shared Store Sync ID first.');if(!firebaseAuth?.currentUser)throw new Error('Not authenticated. Check Firebase connection first.');return dbf.collection('stores').doc(id).collection('ronyal_pos').doc('root')}
function timestampOf(row){const t=row?._posSync?.updatedAt||row?.updatedAt||row?.modifiedAt||row?.createdAt||row?.date||row?._syncedAt;const n=t?Date.parse(t):0;return Number.isFinite(n)?n:0}
function normalizedForCloud(row){const copy={...row};if(!copy._posSync)copy._posSync={updatedAt:new Date(timestampOf(copy)||0).toISOString(),revision:0,deviceId:'legacy',deleted:false};return copy}
function tombstoneKey(storeName,id){return `${storeName}::${String(id)}`}
function getTombstones(){try{return JSON.parse(localStorage.getItem('ronyalSyncTombstones')||'{}')}catch{return {}}}
function queueTombstone(storeName,id){const t=getTombstones();t[tombstoneKey(storeName,id)]={store:storeName,id:String(id),updatedAt:new Date().toISOString(),deviceId:POS_DEVICE_ID,deleted:true};localStorage.setItem('ronyalSyncTombstones',JSON.stringify(t))}
function clearTombstoneIfOlder(storeName,id,meta){const t=getTombstones(),key=tombstoneKey(storeName,id),old=t[key];if(old&&Date.parse(meta?.updatedAt||0)>Date.parse(old.updatedAt||0)){delete t[key];localStorage.setItem('ronyalSyncTombstones',JSON.stringify(t))}}
let autoSyncTimer=null,autoSyncRunning=false,autoSyncAgain=false,autoSyncStarted=false,lastSyncAt=0;
let realtimeUnsubs=[],realtimeStarting=false,realtimeStoreKey='';
function stopRealtimeListeners(){for(const off of realtimeUnsubs){try{off()}catch{}}realtimeUnsubs=[];realtimeStoreKey='';}
function scheduleAutoSync(delay=1200){if(syncApplyingRemote)return;clearTimeout(autoSyncTimer);autoSyncTimer=setTimeout(()=>autoSync().catch(e=>setSyncMessage('Auto-sync paused: '+(e.code?e.code+' — ':'')+e.message)),delay)}
function setSyncMessage(message){const el=document.getElementById('firebaseResult');if(el)el.textContent=message}
async function syncOneLocalRow(base,storeName,row){const ref=base.collection(storeName).doc(String(row.id));const local=normalizedForCloud(row);clearTombstoneIfOlder(storeName,row.id,local._posSync);const snap=await ref.get();if(!snap.exists){await ref.set({...local,_posStore:storeName,_syncedAt:new Date().toISOString()});return 'uploaded'}const cloud=snap.data()||{},cloudTime=timestampOf(cloud),localTime=timestampOf(local);if(localTime>cloudTime){await ref.set({...local,_posStore:storeName,_syncedAt:new Date().toISOString()});return 'uploaded'}if(cloudTime>localTime){syncApplyingRemote=true;try{await put(storeName,stripCloudFields(cloud,String(row.id)))}finally{syncApplyingRemote=false}return 'downloaded'}if(Number(local._posSync?.revision||0)>Number(cloud._posSync?.revision||0)){await ref.set({...local,_posStore:storeName,_syncedAt:new Date().toISOString()});return 'uploaded'}return 'same'}
function stripCloudFields(row,id){const clean={...row,id:row.id||id};delete clean._posStore;delete clean._syncedAt;return clean}
async function syncTombstones(base){const pending=getTombstones();for(const [key,t] of Object.entries(pending)){const rowRef=base.collection(t.store).doc(String(t.id)),rowSnap=await rowRef.get(),cloudRow=rowSnap.exists?rowSnap.data():null;if(cloudRow&&timestampOf(cloudRow)>Date.parse(t.updatedAt||0)){delete pending[key];continue}const ref=base.collection('_tombstones').doc(key),snap=await ref.get(),cloud=snap.exists?snap.data():null;if(!cloud||Date.parse(t.updatedAt)>timestampOf(cloud))await ref.set(t);delete pending[key]}localStorage.setItem('ronyalSyncTombstones',JSON.stringify(pending));const snap=await base.collection('_tombstones').get();let applied=0;const localMaps={};for(const doc of snap.docs){const t=doc.data()||{};if(!t.deleted||!FIREBASE_STORES.includes(t.store)||!t.id)continue;if(!localMaps[t.store])localMaps[t.store]=new Map((await getAll(t.store)).map(x=>[String(x.id),x]));const local=localMaps[t.store].get(String(t.id));if(local&&timestampOf(local)>timestampOf(t))continue;if(local){syncApplyingRemote=true;try{await del(t.store,t.id)}finally{syncApplyingRemote=false}localMaps[t.store].delete(String(t.id));applied++}const localT=getTombstones();delete localT[tombstoneKey(t.store,t.id)];localStorage.setItem('ronyalSyncTombstones',JSON.stringify(localT))}return applied}
async function runWithConcurrency(items,limit,worker){let next=0;const results=new Array(items.length);async function run(){while(true){const i=next++;if(i>=items.length)return;results[i]=await worker(items[i],i)}}await Promise.all(Array.from({length:Math.min(limit,items.length)},run));return results}
async function applyCloudRecord(storeName,docId,cloud){if(!cloud||cloud._deleted)return false;const row=stripCloudFields(cloud,docId),localRows=await getAll(storeName),local=localRows.find(x=>String(x.id)===String(row.id));if(!local||timestampOf(row)>timestampOf(local)||(timestampOf(row)===timestampOf(local)&&Number(row._posSync?.revision||0)>Number(local._posSync?.revision||0))){syncApplyingRemote=true;try{await put(storeName,row)}finally{syncApplyingRemote=false}return true}if(timestampOf(local)>timestampOf(row))scheduleAutoSync(250);return false}
async function startRealtimeListeners(){if(!navigator.onLine||realtimeStarting)return;const cfg=getFirebaseConfig(),sid=(localStorage.getItem('ronyalStoreSyncId')||'').trim();if(!cfg||!sid)return;const key=(cfg.projectId||'')+'|'+sid;if(realtimeStoreKey===key&&realtimeUnsubs.length)return;realtimeStarting=true;try{const dbf=await initFirebase(),base=cloudStoreRoot(dbf);stopRealtimeListeners();realtimeStoreKey=key;for(const n of FIREBASE_STORES){const off=base.collection(n).onSnapshot(snap=>{let changed=false;snap.docChanges().forEach(change=>{if(change.type==='removed')return;const cloud=change.doc.data()||{};applyCloudRecord(n,change.doc.id,cloud).then(didChange=>{if(didChange){changed=true;if(view==='dashboard')scheduleRealtimeRefresh()}}).catch(e=>setSyncMessage('Live update failed: '+e.message))})},err=>setSyncMessage('Live updates paused: '+err.message));realtimeUnsubs.push(off)}const offT=base.collection('_tombstones').onSnapshot(snap=>{snap.docChanges().forEach(change=>{if(change.type==='removed')return;const t=change.doc.data()||{};if(!t.deleted||!FIREBASE_STORES.includes(t.store)||!t.id)return;(async()=>{const rows=await getAll(t.store),local=rows.find(x=>String(x.id)===String(t.id));if(local&&timestampOf(local)>timestampOf(t))return;if(local){syncApplyingRemote=true;try{await del(t.store,t.id)}finally{syncApplyingRemote=false}if(view==='dashboard')scheduleRealtimeRefresh()}const pending=getTombstones();delete pending[tombstoneKey(t.store,t.id)];localStorage.setItem('ronyalSyncTombstones',JSON.stringify(pending))})().catch(e=>setSyncMessage('Live deletion update failed: '+e.message))})},err=>setSyncMessage('Live deletion updates paused: '+err.message));realtimeUnsubs.push(offT)}catch(e){stopRealtimeListeners();setSyncMessage('Live updates unavailable; periodic sync remains active: '+e.message)}finally{realtimeStarting=false}}
let realtimeRefreshTimer=null;function scheduleRealtimeRefresh(){clearTimeout(realtimeRefreshTimer);realtimeRefreshTimer=setTimeout(()=>{if(view==='dashboard'&&!document.querySelector('#main input:focus, #main textarea:focus, #main select:focus'))render().catch(()=>{})},500)}
async function runAutoSync(){const dbf=await initFirebase(),base=cloudStoreRoot(dbf);await startRealtimeListeners();let uploaded=0,downloaded=0,unchanged=0;for(const n of FIREBASE_STORES){const rows=await getAll(n);const results=await runWithConcurrency(rows,6,row=>syncOneLocalRow(base,n,row));for(const result of results){if(result==='uploaded')uploaded++;else if(result==='downloaded')downloaded++;else unchanged++}const snap=await base.collection(n).get();const localMap=new Map((await getAll(n)).map(x=>[String(x.id),x]));const incoming=[];for(const doc of snap.docs){const cloud=doc.data()||{};if(cloud._deleted)continue;const row=stripCloudFields(cloud,doc.id),local=localMap.get(String(row.id));if(!local||timestampOf(row)>timestampOf(local)||(timestampOf(row)===timestampOf(local)&&Number(row._posSync?.revision||0)>Number(local._posSync?.revision||0)))incoming.push({doc,row,local});else if(timestampOf(local)>timestampOf(row)){} }await runWithConcurrency(incoming,6,async item=>{syncApplyingRemote=true;try{await put(n,item.row)}finally{syncApplyingRemote=false}});downloaded+=incoming.length}const deleted=await syncTombstones(base);lastSyncAt=Date.now();setSyncMessage(`Sync active · ${new Date().toLocaleTimeString()} · live updates enabled · uploaded ${uploaded}, downloaded ${downloaded}, unchanged ${unchanged}, deletions applied ${deleted}.`);return {uploaded,downloaded,unchanged,deleted}}
