function isScannerCancellation(error){
 const message=String(error?.message||error||'').toLowerCase();
 return /cancel(?:led|ed|lation)?|dismiss(?:ed|al)?|user.?back|back.?pressed|scan.?closed|activity.?finish/.test(message);
}
async function scanNativeBarcode(){
 const scanner=window.RonyalBarcodeScanner;
 if(!scanner||typeof scanner.scanBarcode!=='function')throw new Error('Android native scanner is unavailable.');
 const result=await scannerWithTimeout(Promise.resolve().then(()=>scanner.scanBarcode()),15000,'Native scanner timed out. Close any Android scanner screen and try Web mode.');
 return String(result?.barcode||result?.barcodes?.[0]?.rawValue||'').trim();
}

// Offline camera scanner. Timeouts and a single active session keep a stalled camera/detector
// from trapping the UI. This uses only the browser's built-in BarcodeDetector (no network).
let ronyalScannerSessionActive=false;
async function scanWithCameraFallback(title='Scan barcode'){
 if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera access is unavailable in this browser/app.');
 if(!('BarcodeDetector' in window))throw new Error('This device does not support built-in offline barcode decoding. Choose Native mode or use an APK with a bundled offline decoder.');
 if(ronyalScannerSessionActive)throw new Error('A scanner is already open. Close it before starting another scan.');
 return new Promise((resolve,reject)=>{
  const wrap=document.createElement('div');wrap.id='ronyalOfflineScanner';wrap.className='scanner-modal-back';
  wrap.innerHTML=`<div class="scanner-mini-modal"><div class="scanner-modal-head"><strong class="scanner-modal-title"></strong><button type="button" id="ronyalOfflineClose" class="secondary scanner-close">✕</button></div><video id="ronyalOfflineVideo" autoplay muted playsinline></video><p id="ronyalOfflineStatus" class="scanner-modal-status">Starting camera… Point the camera at the barcode.</p></div>`;
  document.body.appendChild(wrap);wrap.querySelector('.scanner-modal-title').textContent=title;
  let stream=null,finished=false,detector=null,raf=0,detecting=false,startupTimeout=0;
  ronyalScannerSessionActive=true;
  const stopStream=s=>{try{s?.getTracks?.().forEach(t=>t.stop())}catch{}};
  const clean=()=>{if(startupTimeout)clearTimeout(startupTimeout);if(raf)cancelAnimationFrame(raf);try{const v=wrap.querySelector('video');if(v){v.pause();v.srcObject=null}stopStream(stream)}catch{}wrap.remove();ronyalScannerSessionActive=false};
  const done=(err,value)=>{if(finished)return;finished=true;clean();err?reject(err):resolve(value)};
  wrap.querySelector('#ronyalOfflineClose').onclick=()=>done(new Error('Barcode scan cancelled.'));
  wrap.addEventListener('click',e=>{if(e.target===wrap)done(new Error('Barcode scan cancelled.'))});
  startupTimeout=setTimeout(()=>done(new Error('Camera startup timed out. Check camera permission, close other camera apps, and try again.')),12000);
  (async()=>{
   try{
    const formats=['ean_13','ean_8','upc_a','upc_e','code_128','code_39','itf','qr_code'];
    try{detector=new BarcodeDetector({formats})}catch{detector=new BarcodeDetector()}
    const pendingStream=navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});
    // If the permission/device prompt resolves after the timeout or close, immediately release it.
    pendingStream.then(s=>{if(finished)stopStream(s)}).catch(()=>{});
    stream=await scannerWithTimeout(pendingStream,12000,'Camera startup timed out. Check camera permission and try again.');
    if(finished){stopStream(stream);return}
    clearTimeout(startupTimeout);
    const video=wrap.querySelector('#ronyalOfflineVideo');video.srcObject=stream;
    await scannerWithTimeout(video.play(),8000,'Camera preview failed to start. Close the scanner and try again.');
    if(finished)return;
    wrap.querySelector('#ronyalOfflineStatus').textContent='Offline scanner ready — point the camera at the barcode.';
    const scan=async()=>{
     if(finished||!wrap.isConnected||detecting)return;
     detecting=true;
     try{
      if(video.readyState>=2){
       let detectPromise;
       try{detectPromise=detector.detect(video)}catch(e){throw e}
       const codes=await scannerWithTimeout(detectPromise,5000,'Barcode detection stopped responding. Close the scanner and try again.');
       if(finished)return;
       if(codes?.length){const value=String(codes[0].rawValue||'').trim();if(value){done(null,value);return}}
      }
     }catch(e){if(/timed out|stopped responding/i.test(String(e?.message||e))){done(new Error(e.message));return}}
     finally{detecting=false}
     if(!finished&&wrap.isConnected)raf=requestAnimationFrame(scan);
    };
    raf=requestAnimationFrame(scan);
   }catch(e){done(new Error('Camera scanner could not start: '+(e?.message||e)))}
  })();
 });
}
function isNativePos(){return !!(window.Capacitor&&typeof window.Capacitor.isNativePlatform==='function'&&window.Capacitor.isNativePlatform())}
function scannerCapabilities(){
 const native=!!(window.RonyalBarcodeScanner&&typeof window.RonyalBarcodeScanner.scanBarcode==='function');
 const camera=!!(navigator.mediaDevices?.getUserMedia&&('BarcodeDetector' in window));
 return {native,camera};
}
function getScannerMode(){const mode=localStorage.getItem('ronyalScannerMode')||'auto';return ['auto','native','camera'].includes(mode)?mode:'auto'}
function scannerModeLabel(mode){return mode==='native'?'Native':mode==='camera'?'Web camera':'Auto'}
function showScannerModeMenu(anchor){
 document.querySelectorAll('.scanner-mode-menu').forEach(el=>el.remove());
 const caps=scannerCapabilities(),current=getScannerMode(),menu=document.createElement('div');menu.className='scanner-mode-menu';
 const options=[
  {key:'auto',name:'Auto',desc:'Choose the best supported scanner',available:true},
  {key:'native',name:'Native scanner',desc:'Android app scanner',available:caps.native},
  {key:'camera',name:'Web camera',desc:'Built-in offline barcode detection',available:caps.camera}
 ];
 menu.innerHTML=options.map(o=>`<button type="button" class="scanner-mode-option ${current===o.key?'selected':''}" data-mode="${o.key}"><span class="scanner-mode-copy"><strong>${o.name}</strong><small>${o.desc}</small></span></button>`).join('');
 document.body.appendChild(menu);
 const r=anchor.getBoundingClientRect(),mw=Math.min(280,window.innerWidth-20);menu.style.width=mw+'px';menu.style.left=Math.max(10,Math.min(r.right-mw,window.innerWidth-mw-10))+'px';menu.style.top=Math.min(window.innerHeight-menu.offsetHeight-10,r.bottom+6)+'px';
 menu.querySelectorAll('[data-mode]').forEach(btn=>btn.onclick=()=>{const mode=btn.dataset.mode,available=mode==='auto'||(mode==='native'?caps.native:caps.camera);if(!available){toast(mode==='native'?'Native scanner is not available in this installed app.':'Web camera barcode detection is not supported on this device.');return}localStorage.setItem('ronyalScannerMode',mode);menu.remove();updateScannerModeIndicators();toast('Scanner mode: '+scannerModeLabel(mode))});
 const outside=e=>{if(!menu.contains(e.target)&&!anchor.contains(e.target)){menu.remove();document.removeEventListener('pointerdown',outside,true)}};
 setTimeout(()=>document.addEventListener('pointerdown',outside,true),0);
}
function updateScannerModeIndicators(){const mode=getScannerMode();document.querySelectorAll('[data-scanner-mode-menu]').forEach(b=>{b.textContent='▾';b.title='Scanner mode: '+scannerModeLabel(mode);b.setAttribute('aria-label','Scanner mode: '+scannerModeLabel(mode))});const label=document.getElementById('scannerStatus');if(label&&view==='pos')label.dataset.mode=scannerModeLabel(mode)}
document.addEventListener('click',function scannerModeMenuDelegation(e){const b=e.target.closest('[data-scanner-mode-menu]');if(!b)return;e.preventDefault();e.stopPropagation();showScannerModeMenu(b)});
let ronyalBarcodeOperationActive=false;
async function runBarcodeScan(mode,title){
 if(ronyalBarcodeOperationActive)throw new Error('A barcode scan is already in progress. Please wait or close the scanner.');
 ronyalBarcodeOperationActive=true;
 try{
 const caps=scannerCapabilities();
 const tryNative=async()=>{if(!caps.native)throw new Error('Android native scanner is not available in this browser.');return await scanNativeBarcode()};
 const tryCamera=async()=>{if(!caps.camera)throw new Error('Built-in offline camera scanning is not supported on this device/browser.');return await scanWithCameraFallback(title)};
 if(mode==='native')return tryNative();
 if(mode==='camera')return tryCamera();
 // Auto: native bridge first in the installed app, then supported offline camera fallback.
 if(isNativePos()&&caps.native){
  try{return await tryNative()}
  catch(nativeError){
   // Android Back / Cancel means the user intentionally ended the scan.
   // Never open the web camera as a side effect of cancelling the native scanner.
   if(isScannerCancellation(nativeError))throw nativeError;
   if(caps.camera)return tryCamera();
   throw nativeError;
  }
 }
 if(caps.camera)return tryCamera();
 if(caps.native)return tryNative();
 throw new Error('No supported scanner is available. This device needs an APK with a bundled offline barcode decoder.');
 }finally{ronyalBarcodeOperationActive=false}
}
async function startProductScanner(targetName='barcode'){
 const targetLabel=targetName==='pieceBarcode'?'individual-item':'pack';
 try{
  const barcode=await runBarcodeScan(getScannerMode(),`Scan ${targetLabel} barcode`);
  if(!barcode){toast('No barcode detected. Please try again.');return}
  const input=document.querySelector(`#productForm input[name="${targetName}"]`);
  if(input){input.value=barcode;input.dispatchEvent(new Event('input',{bubbles:true}));input.focus()}
  toast('Barcode scanned successfully!');
 }catch(e){if(!isScannerCancellation(e))toast('Scanner unavailable: '+String(e?.message||e).slice(0,170))}
}
async function startScanner(){
 try{const barcode=await runBarcodeScan(getScannerMode(),'Scan product barcode');if(!barcode){toast('No barcode detected. Please try again.');return}processScannedBarcode(barcode,false)}
 catch(e){if(!isScannerCancellation(e))toast('Scanner unavailable: '+String(e?.message||e).slice(0,170))}
}

// Modal navigation handling without observing every attribute change in the entire app.
// The previous broad observer was needlessly firing during form/UI updates and could stall
// slower mobile browsers. Watch only structural changes, then coalesce updates to one frame.
(function setupDockForOverlays(){
 const dock=document.getElementById('mobileNav'); if(!dock)return;
 let scheduled=false;
 const overlayOpen=()=>!!document.querySelector('.modal-back:not(.hidden),dialog[open],[role="dialog"]:not(.hidden)');
 const sync=()=>{
   scheduled=false;
   const open=overlayOpen();
   dock.classList.toggle('nav-hidden',open);
   document.body.classList.toggle('pos-overlay-open',open);
 };
 const scheduleSync=()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(sync)};
 const observer=new MutationObserver(scheduleSync);
 const main=document.getElementById('main');
 const overlay=document.getElementById('overlay');
 const productMount=document.getElementById('productFormMount');
 [main,overlay,productMount].filter(Boolean).forEach(node=>observer.observe(node,{subtree:true,childList:true}));
 document.addEventListener('keydown',e=>{if(e.key==='Escape')scheduleSync()});
 document.addEventListener('click',e=>{if(e.target.closest('#closeProduct,#cancelProduct,#closeScanner'))setTimeout(scheduleSync,0)});
 sync();
})();

// Mobile dock behavior: hide on downward scroll and while an input is focused,
// reveal on upward scroll or when the user returns to the top of the page.
(function setupMobileDockAutoHide(){
 const dock=document.getElementById('mobileNav');
 if(!dock)return;
 let lastY=window.scrollY||0, raf=false;
 const hide=()=>dock.classList.add('nav-hidden');
 const show=()=>dock.classList.remove('nav-hidden');
 window.addEventListener('scroll',()=>{
  if(raf)return; raf=true;
  requestAnimationFrame(()=>{
   const y=window.scrollY||0, delta=y-lastY;
   if(y<24)show();
   else if(delta>5)hide();
   else if(delta< -5)show();
   lastY=y; raf=false;
  });
 },{passive:true});
 document.addEventListener('focusin',e=>{
  if(e.target.matches('input,select,textarea,[contenteditable="true"]'))hide();
 });
 document.addEventListener('focusout',e=>{
  if(e.target.matches('input,select,textarea,[contenteditable="true"]')){
   window.setTimeout(()=>{if(!document.activeElement?.matches('input,select,textarea,[contenteditable="true"]'))show()},180);
  }
 });
 // Tap outside the dock to bring it back after it has hidden.
 document.addEventListener('pointerdown',e=>{if(dock.classList.contains('nav-hidden')&&!dock.contains(e.target)&&!e.target.matches('input,select,textarea'))show()},{passive:true});
})();

