document.addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)setView(b.dataset.go)});document.getElementById('lockPosButton')?.addEventListener('click',async()=>{clearLogin();view='dashboard';await render();await showPinLockScreen();if(isUnlocked())await render()});window.addEventListener('beforeunload',()=>{if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop())});
