// Android/WebView Back-button support for POS dialogs and form popups.
// A temporary history entry lets Android's normal WebView goBack() close a popup first.
(function setupPosBackButton(){
 const STATE_KEY='__ronyalPosPopup';
 let popupEntryActive=!!(history.state&&history.state[STATE_KEY]);
 let handlingBack=false;
 let scheduled=false;
 const visiblePopups=()=>Array.from(document.querySelectorAll('.modal-back, .pin-backdrop')).filter(el=>{
  const st=getComputedStyle(el);
  return st.display!=='none'&&st.visibility!=='hidden'&&el.getClientRects().length>0;
 });
 const isProtectedPopup=el=>!!(el&&(el.classList.contains('pin-backdrop')||el.id==='saleConfirmBackdrop'||el.querySelector('#saleConfirmTitle')));
 let lastDashboardBackAt=0;
 const handleDashboardBack=()=>{
  const now=Date.now();
  if(now-lastDashboardBackAt<2200){
   lastDashboardBackAt=0;
   try{window.RonyalApp?.exitApp?.()}catch(_){}
   return;
  }
  lastDashboardBackAt=now;
  toast('Press Back again to exit Ronyal POS');
 };
 const closePopup=()=>{
  const popups=visiblePopups();
  if(!popups.length)return false;
  // A sale confirmation must never be dismissed by Android Back or Escape.
  const top=popups[popups.length-1];
  if(isProtectedPopup(top))return false;
  const buttons=Array.from(top.querySelectorAll('button'));
  const closeButton=buttons.find(b=>/^(✕|×|close|cancel|back|discard)$/i.test((b.textContent||'').trim())||/close|cancel|back/i.test((b.id||'')+' '+(b.getAttribute('aria-label')||'')));
  if(closeButton){closeButton.click();return true;}
  // Fallback for simple confirmation overlays that do not expose a close control.
  const id=top.id;
  if(id==='saleConfirmBackdrop'){
   const cancel=top.querySelector('button.secondary,button[data-cancel]');
   if(cancel){cancel.click();return true;}
  }
  // Remove only the popup container, not the underlying POS screen or its data.
  top.remove();
  return true;
 };
 const reconcile=()=>{
  scheduled=false;
  const open=visiblePopups().length>0;
  if(open&&!popupEntryActive){
   try{history.pushState({...history.state,[STATE_KEY]:true},'',location.href);popupEntryActive=true;}catch(_){/* WebView may restrict history state */}
  }else if(!open&&popupEntryActive&&!handlingBack){
   // A popup was closed using its on-screen button; discard its temporary history entry.
   popupEntryActive=false;
   try{history.back();}catch(_){}
  }
 };
 const schedule=()=>{if(scheduled)return;scheduled=true;setTimeout(reconcile,0)};
 window.addEventListener('popstate',()=>{
  const popups=visiblePopups();
  if(popups.length){
   const top=popups[popups.length-1];
   if(isProtectedPopup(top)){
    // Back was pressed while sale confirmation is active: keep it open and
    // restore a temporary history entry so repeated Back presses cannot dismiss it.
    popupEntryActive=false;
    try{history.pushState({...history.state,[STATE_KEY]:true},'',location.href);popupEntryActive=true;}catch(_){/* WebView may restrict history state */}
    return;
   }
   handlingBack=true;
   popupEntryActive=false;
   closePopup();
   // The popup's own close handler may update the DOM asynchronously.
   setTimeout(()=>{handlingBack=false;reconcile();},80);
  }else{
   popupEntryActive=!!(history.state&&history.state[STATE_KEY]);
  }
 });
 document.addEventListener('keydown',e=>{
  if((e.key==='Escape'||e.key==='BrowserBack')&&visiblePopups().length){
   const popups=visiblePopups(),top=popups[popups.length-1];
   if(isProtectedPopup(top)){
    e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();return;
   }
   e.preventDefault();e.stopPropagation();closePopup();
  }
 },true);
 // Capacitor's native Android hardware Back event does not reliably create a
 // browser popstate. Route it through the same popup rules as browser Back.
 const handleNativeBack=()=>{
  // Let the native ML Kit scanner activity consume Back while it is active.
  if(ronyalBarcodeOperationActive&&!document.getElementById('ronyalOfflineScanner'))return;
  const webScanner=document.getElementById('ronyalOfflineScanner');
  if(webScanner){webScanner.querySelector('#ronyalOfflineClose')?.click();return;}
  const scannerMenus=document.querySelectorAll('.scanner-mode-menu');
  if(scannerMenus.length){scannerMenus.forEach(el=>el.remove());return;}
  const popups=visiblePopups();
  if(popups.length){
   if(isProtectedPopup(popups[popups.length-1]))return;
   closePopup();return;
  }
  // Never close the app on a single Back press. Secondary screens return to Dashboard;
  // Dashboard requires a second Back press within 2.2 seconds to exit.
  if(typeof view!=='undefined'&&view!=='dashboard'&&typeof setView==='function'){
   setView('dashboard');return;
  }
  handleDashboardBack();
 };
 let nativeBackListenerAttached=false,nativeBackListenerPending=false;
 const attachNativeBackHandler=()=>{
  if(nativeBackListenerAttached||nativeBackListenerPending||!window.RonyalApp||typeof window.RonyalApp.addListener!=='function')return;
  nativeBackListenerPending=true;
  try{
   Promise.resolve(window.RonyalApp.addListener('backButton',handleNativeBack)).then(()=>{
    nativeBackListenerAttached=true;
   }).catch(e=>{
    console.warn('Could not attach native Android Back handler:',e);
   }).finally(()=>{nativeBackListenerPending=false});
  }catch(e){nativeBackListenerPending=false;console.warn('Could not attach native Android Back handler:',e)}
 };
 // The APK build injects its native bridge near </body>, after this script runs.
 // Retry briefly so the native Back listener is still registered reliably.
 attachNativeBackHandler();
 const nativeBackBridgeWait=setInterval(()=>{
  attachNativeBackHandler();
  if(nativeBackListenerAttached)clearInterval(nativeBackBridgeWait);
 },100);
 setTimeout(()=>clearInterval(nativeBackBridgeWait),10000);
 const observer=new MutationObserver(schedule);
 observer.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['class','style','hidden']});
 // Catch dialogs already open when this helper initializes.
 schedule();
})();

