(function(){
  if(window.__rssDesktopScrollV76)return;window.__rssDesktopScrollV76=true;
  const tools=document.getElementById('desktopScrollTools');
  const up=document.getElementById('scrollPageUp');
  const down=document.getElementById('scrollPageDown');
  const isDesktop=()=>window.matchMedia('(min-width: 901px)').matches;
  const scroller=()=>document.scrollingElement||document.documentElement;
  function refresh(){
    if(!tools)return;
    const desktop=isDesktop();
    tools.hidden=!desktop;
    if(!desktop)return;
    const el=scroller(),max=Math.max(0,el.scrollHeight-el.clientHeight),y=el.scrollTop||window.scrollY||0;
    if(up)up.disabled=y<4;
    if(down)down.disabled=max-y<4;
    tools.style.opacity=max<4?'.45':'1';
  }
  function pageScroll(amount){
    const el=scroller();
    const step=Math.max(280,Math.round((window.innerHeight||700)*.72));
    const destination=amount<0?0:Math.min(el.scrollHeight,el.scrollTop+step);
    if(typeof window.scrollTo==='function')window.scrollTo({top:destination,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
    else el.scrollTop=destination;
    setTimeout(refresh,220);
  }
  up?.addEventListener('click',()=>pageScroll(-1));
  down?.addEventListener('click',()=>pageScroll(1));
  window.addEventListener('scroll',refresh,{passive:true});
  window.addEventListener('resize',refresh,{passive:true});
  document.addEventListener('wheel',function(e){
    if(!isDesktop()||e.defaultPrevented||e.ctrlKey||Math.abs(e.deltaY)<1)return;
    const target=e.target instanceof Element?e.target:null;
    if(!target||target.closest('input,textarea,select,[contenteditable="true"]'))return;
    // Let tables, carts, dialogs and other genuine inner scrollers consume the wheel first.
    let node=target;
    while(node&&node!==document.body&&node!==document.documentElement){
      const style=getComputedStyle(node);
      const oy=style.overflowY;
      if((oy==='auto'||oy==='scroll')&&node.scrollHeight>node.clientHeight+1){
        const canUp=node.scrollTop>0,canDown=node.scrollTop+node.clientHeight<node.scrollHeight-1;
        if((e.deltaY<0&&canUp)||(e.deltaY>0&&canDown))return;
      }
      node=node.parentElement;
    }
    // Explicitly route wheel movement to the document when no nested panel can scroll.
    const el=scroller(),max=el.scrollHeight-el.clientHeight;
    if(max>1){
      const before=el.scrollTop;
      const next=Math.max(0,Math.min(max,before+e.deltaY));
      if(next!==before){e.preventDefault();el.scrollTop=next;refresh();}
    }
  },{passive:false});
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',refresh,{once:true});else refresh();
})();
